import json
tm = json.load(open('timing.json'))
gl = tm['glosses']
S = [
('s01',0.0,2.6,'Ey tahammülsüz hasta!','HAZIR (referans). Gece odası, huzursuz hasta, duvar saati, kandil.'),
('s02',2.6,7.1,'İnsan bu dünyaya keyif sürmek ve lezzet almak için gelmediğine,','''Boya darbesiyle geceden aydınlık bir dünyaya geçilir (geçiş motorda). Güneşli, yumuşak tepeli küçük bir dünya: adam (2.94 "İnsan") soldan yürüyerek gelip tepede durur. "bu dünyaya" (3.46): kamera hafif geri çekilir, dünyanın kavisli ufku/tepeleri, bir ağaç. "keyif sürmek" (3.96–4.70): ağaçlar arasına bir hamak, minder ve ince belli çay bardağı POP ile belirir. "lezzet almak" (5.10–5.74): meyve tepsisi (nar, üzüm, incir), tatlılar parıltıyla belirir. "gelmediğine" (6.06–6.66): bütün bu keyif/lezzet nesneleri balon/kabarcık gibi yukarı süzülüp parıltıya ve kuma dönüşerek dağılır; adam sakin, onları seyreder. Sona doğru boşalan tepe, rüzgârda otlar.'''),
('s03',7.1,9.9,'mütemadiyen gelenlerin gitmesi','''Dünya misafirhanesi: ortada akrilik bir kervansaray (han) — iki kapılı, kubbeli taş yapı. Soldan sürekli yolcular gelir (hepsi erkek, farklı yaşlar/boylar, sade siluetler ama aynı akrilik üslup; bohçalı, asalı), soldaki kapıdan girer, sağdaki kapıdan çıkıp sağdan kadrajı terk eder. Akış hiç durmaz (7.52 "mütemadiyen" ile hızlanan, kesintisiz bir yürüyüş sırası). Gökte güneş hızla yay çizer (zaman akıyor). Kamera hafifçe sağa kayar. Yolcuları M.drawMan ile küçük ölçekte çiz (ayak kaymasın).'''),
('s04',9.9,12.5,'ve gençlerin ihtiyarlaşması','''Yandan yakın plan: adam yerinde yürür (arka plan kayar, ayak kaymaz) ve yürürken yaşlanır: 10.36 "gençlerin" genç, dik, dinç; 11.0–11.86 "ihtiyarlaşması" boyunca saç-sakal ağarır (age 0→1), sırtı kamburlaşır, adımları kısalır, eline baston gelir (cane). Arkada mevsimler döner: bahar çiçekleri → yaz yeşili → güz (turuncu yapraklar uçuşur) → kış (kar taneleri). Arka plan katmanları paralaksla kayar.'''),
('s05',12.5,17.3,'ve mütemadiyen zeval ve firakta yuvarlanması şahittir.','''Çark-ı felek: büyük, ahşap, boyalı bir dönme dolap/su çarkı üst yarıda (y≈250–1150) ağır ağır döner. 12.96 "mütemadiyen" dönüş başlar/hızlanır. Kollarında küçük saksılar/çiçekler, kuş çiftleri, yapraklar: tepeye çıkan çiçek açar, aşağı inerken solar ("zeval" 13.72). "firakta" (14.22): bir dalda yan yana duran iki kuş ayrı yönlere uçar. "yuvarlanması" (14.62–15.34): çark daha da hızlanır, yapraklar savrulur. "şahittir" (15.62–16.24): kamera geri çekilir; çark ufukta batan güneşin önünde siluetleşir. Bu sahnede üç anlam üst üste çıkar (12.96, 13.72, 14.22): alt bant (y 1200–1560) sakin olsun.'''),
('s06',17.3,22.1,'Hem insan, zîhayatın en mükemmeli en yükseği','''Canlılar sırası (Kurzgesagt tarzı dizilim): 18.76 "zîhayatın" ile sırayla POP: uğur böceği, arı, su kabarcığı içinde balık, kuş, tavşan, ceylan, koyun — her biri küçük bir çimen öbeği/kaide üstünde, sevimli ama sade akrilik. 19.5 "en mükemmeli": ortada adam belirir, yumuşak altın bir ışık hüzmesi üstüne düşer (hale DEĞİL, sahne ışığı). 20.88 "en yükseği": canlılar basamak basamak yükselen bir merdiven/piramit düzenine geçer, adam en üst basamakta; kamera yukarı eğilir.'''),
('s07',22.1,24.3,'ve cihazatça en zengini','''İnfografik: adamın yakın büst planı (yandan), etrafında yarım halka hâlinde sırayla POP eden simgeler, ince altın çizgilerle ona bağlı: göz, kulak, el, kalp, akıl (başta yanan küçük bir kandil/ışık), dil/tat (bir damla bal), burun/koku (bir gül). 22.40 "cihazatça" ile başlar, her simge ~0.15 sn arayla; 23.1–23.72 "en zengini": simgeler parlar, halka hafifçe döner, altın parıltılar. Yazı/etiket yok.'''),
('s08',24.3,27.3,'belki zîhayatların sultanı hükmünde iken,','''Gün batımı altın ışığında bir kaya tepesinde adam ayakta; aşağıda s06'daki canlılar etrafında toplanmış, ona bakıyor. 24.98 "zîhayatların": canlılar sırayla başını kaldırır. 25.72 "sultanı": yukarıdan altın bir taç (R.crown) yavaşça iner, başına oturur, parlar. 26.14–26.86 "hükmünde iken": hafif kamera itmesi, tacın parıltısı, adamın duruşu dikleşir (asil ama kibirli değil).'''),
('s09',27.3,32.0,'geçmiş lezzetleri ve gelecek belaları düşünmek vasıtasıyla,','''Adam ortada bir taşın üstünde oturur. Altında soldan sağa ince bir zaman çizgisi (geçmiş ← • → gelecek), adam "şimdi" noktasında. 27.76 "geçmiş lezzetleri": solda soluk, sepya bir düşünce bulutu: bir ziyafet sofrası, bahar bahçesi — tozlaşıp ufalanarak kayboluyor; adam omzunun üstünden geriye, hüzünle bakar. 29.36 "gelecek belaları": sağda koyu fırtına bulutu, şimşek, yaklaşan dalgalar; adam sağa endişeyle döner. 30.40 "düşünmek vasıtasıyla": iki bulut başının çevresinde döner, ağırlaşır; adam başını ellerinin arasına alır.'''),
('s10',32.0,35.5,'hayvana nisbeten en edna bir derecede','''Büyük bir terazi (akrilik pirinç/ahşap). 32.38 "hayvana nisbeten": bir kefede güneşli çimende keyifle otlayan koyun (kelebekler), öbür kefede adam (başında küçük yağmur bulutu, endişeli). 34.18 "en edna": terazi adamın kefesi AŞAĞI inecek şekilde ağır ağır yatar (aşağılık derecesi), koyun güneşte yukarıda kalır. 34.54–35.2 "bir derecede": terazi sallanıp oturur.'''),
('s11',35.5,39.6,'ancak kederli, meşakkatli bir hayat geçiriyor.','''Adam sırtında ağır bir çuval/yükle dik, uzun bir yokuşu ağır ağır tırmanır (yürüyüş döngüsü, öne eğik gövde, kısa adımlar); kamera yanından onunla birlikte kayar (yol sürekli yukarı). Gri-mavi gök, rüzgâr, başının üstünde onu izleyen küçük bir yağmur bulutu (36.24 "kederli"). 37.08 "meşakkatli": tökezler, bir an durup alnını siler, sonra devam eder. 37.9–38.68: yokuşun uzadığı görülür.'''),
('s12',39.6,48.2,'Demek insan, bu dünyaya yalnız güzel yaşamak için ve rahatla ve safa ile ömür geçirmek için gelmemiştir.','''Aydınlık. 40.38 "Demek insan": adam sade bir tepede ayakta. 41.2–43.44 "bu dünyaya yalnız güzel yaşamak için": yanında dev, yanardöner bir sabun köpüğü şişer; içinde rüya gibi bir bahçe: güzel bir ev, çiçekler. 44.08–46.48 "rahatla ve safa ile ömür geçirmek": köpüğün içinde adamın hayali bir eşi (aynı adam) iki ağaç arasındaki hamakta çay içerek sallanır, köpüğün içinde güneş hızla döner (ömür geçiyor). 46.56 "gelmemiştir": köpük PATLAR, damlacıklar ve parıltılar saçılır; gerçek adam sakin, düşünceli kalır, başını kaldırıp ufka bakar. 47.3–48.2: yumuşak sessiz an.'''),
('s13',48.2,51.7,'Belki azîm bir sermaye elinde bulunan insan,','''Şafak ışığı. Adam ayakta, avuçlarını öne açar. 49.18 "azîm": avuçlarında bir kıvılcım belirir ve hızla büyüyerek kocaman, ışınlar saçan altın bir ışık küresine (hazine) dönüşür. 49.68 "sermaye": kürenin etrafında altın sikkeler/mücevherler yörüngede döner (R.coin). 50.30–51.34 "elinde bulunan insan": kamera ellere doğru iter, adamın yüzü ışıkla aydınlanır.'''),
('s14',51.7,58.5,'burada ticaret ile ebedî daimî bir hayatın saadetine çalışmak için gelmiştir.','''Çarşı ve yol. 52.08 "burada ticaret ile": dünyadaki bir pazar tezgâhında adam ışık küresinden sikkeler verir, karşılığında ışıktan fidanlar/tohumlar alır (karşıda satıcı yok; tezgâh ve teraziler yeter ya da sade bir esnaf figürü — erkek). 53.82 "ebedî" (sonsuz): kamera yukarı kayar, uzakta yüksek bir dağın üstünde ışıyan ebedî bahçe kapısı (R.gardenGate) ve sonsuza kıvrılan bir yol görünür. 55.16 "saadetine": bahçe daha da parlar, kuşlar. 56.34–57.6 "çalışmak için gelmiştir": adam yol boyunca ışık fidanları diker, her fidandan bahçeye doğru ışık akar; adam gayretle yürür.'''),
('s15',58.5,62.5,'Onun eline verilen sermaye de ömürdür.','''Yakın plan: adamın elleri altın ışık küresini tutar (s13'e geri dönüş). 59.24–60.14 "Onun eline verilen": küre ellerde dinginlikle parlar. 60.24 "sermaye de": küre titreşir, biçim değiştirmeye başlar. 61.2 "ömürdür": küre zarif bir dönüşümle bir KUM SAATİNE (R.hourglass) dönüşür; altın kum akmaya başlar (kum taneleri sikkelerle aynı altın). Arka plan sıcak, sade.'''),
('s16',62.5,71.5,'Eğer hastalık olmazsa sıhhat ve âfiyet gaflet verir, dünyayı hoş gösterir, âhireti unutturur.','''Güneşli güzel bir patika; tek, sürekli sahne, kamera adamla birlikte kayar. 63.06 "Eğer hastalık olmazsa": adam dinç, kollarını sallayarak yürür. 65.02 "sıhhat ve âfiyet": etrafında taze yeşil-altın bir sağlık parıltısı. 66.30 "gaflet": başının çevresine pembe-lila yumuşak bir sis/peçe sarılır, göz kapakları yarı kapanır, dalgın gülümser. 67.58 "dünyayı hoş gösterir": dünya aşırı parlaklaşır: ağaçlardan sarkan parlak süsler, POP eden çiçekler, parıltılar; adam büyülenmiş, parlak şeylere bakar. 69.70 "âhireti unutturur": arka planda uzak bir tepede ebedî bahçe kapısı (R.gardenGate) hafifçe ışır, sonra sis üstüne çöker ve kaybolur; adam ona sırtı dönük yürümeye devam eder.'''),
('s17',71.5,74.8,'Kabri ve ölümü hatırına getirmek istemiyor,','''Alacakaranlık yolu. 72.14 "Kabri ve ölümü": yol kenarında servilerin arasında sakin bir mezarlık (birkaç basit mezar taşı, R.tombstone, R.cypress). Adam yürürken fark eder; 72.92–74.28 "hatırına getirmek istemiyor": başını çevirir, elini yüzüne siper eder, adımlarını hızlandırır; başının üstünde bir mezar taşı düşünce balonu belirir ve adam onu eliyle iter, balon "puf" diye söner. Saygılı, korkutucu değil.'''),
('s18',74.8,79.7,'sermaye-i ömrünü bâd-i heva boş yere sarf ettiriyor.','''Ortada büyük kum saati (R.hourglass, s15'teki aynı). 75.28 "sermaye-i ömrünü": kum saati parlar, altın kum akar. 76.86 "bâd-i heva": camda bir çatlak açılır, sağdan esen rüzgâr altın kumu çatlaktan dışarı savurur; kum taneleri ve altın sikkeler havada uçuşup sağa doğru dağılarak kaybolur. Aşağıda küçük ölçekte adam bir kelebeğin peşinde koşar, olanların farkında değil. 77.74–79.04 "boş yere sarf ettiriyor": kum seviyesi hızla düşer. İki anlam üst üste çıkar (75.28, 76.86).'''),
('s19',79.7,83.3,'Hastalık ise birden gözünü açtırır.','''Odaya dönüş (scenes/_room.js; s01 ile aynı oda, gece). Adam yatakta hasta (alında ateş parıltısı), göz kapakları yarı kapalı, başının çevresinde s16'daki pembe-lila gaflet sisi hâlâ var. 80.42 "Hastalık ise": ateş nabzı güçlenir. 81.56 "birden": keskin an — sis cam gibi çatlayıp dağılır, parlak bir ışık çakar; 82.0 "gözünü açtırır": gözleri kocaman açılır, yatakta hafifçe doğrulur. Kamera yüzüne hızlıca iter. Gerekirse kendi yatma/doğrulma pozunu sahne dosyanda yaz (_room.js'i değiştirme; ROOM, drawRoom, drawBedBack kullan).'''),
('s20',83.3,85.7,'Vücuduna ve cesedine der ki:','''Oda, adam yatakta doğrulmuş oturur (orta plan). 83.86 "Vücuduna": vücudunun çevresinde yumuşak, ışıyan bir kontur belirir. 84.48 "cesedine": göğsündeki ateş parıltısı sıcak bir köze dönüşür. 84.96 "der ki": o közden halka halka yumuşak ses dalgaları yayılır (hastalığın bedene "konuşması"); dalgalar sıradaki sözlere hazırlık.'''),
('s21',85.7,90.5,'"Lâyemut değilsin, başıboş değilsin, bir vazifen var.','''İç dünya: koyu lacivert, yıldızlı, sade bir uzam (uzay değil; gece göğü/su yüzeyi gibi). Üç vuruş: 86.10 "Lâyemut değilsin": büyük kum saati, kum azalmış, son taneler akıyor; yanında adamın silueti. 87.80 "başıboş değilsin": büyük bir pusula: ibresi çılgınca döner, sonra yukarıdaki parlak bir yıldıza kilitlenir. 89.26 "bir vazifen var": adamın ellerinde yanan bir fener (R.lantern) belirir, ışığı etrafı aydınlatır.'''),
('s22',90.5,93.8,'Gururu bırak, seni yaratanı düşün,','''90.94 "Gururu": adam başında s08'deki altın taçla, göğsü kabarık, burnu havada durur. 91.32 "bırak": tacı çıkarıp bırakır; taç düşerken parlaması söner, adamın duruşu yumuşar, başı tevazuyla eğilir. 92.36 "seni yaratanı düşün": adam bakışını yukarı kaldırır, kamera yukarı eğilir: muhteşem bir gök — yıldızlar, ufukta doğan güneş, kuş sürüsü, dağlar (yaratılış delilleri; asla tasvir yok, yalnız ışık ve doğa).'''),
('s23',93.8,97.6,'kabre gideceğini bil, öyle hazırlan."','''Alacakaranlıkta kıvrılan bir yol, sonunda servilerle çevrili sakin bir mezarlık (s17 ile uyumlu). 94.18 "kabre gideceğini bil": adam yolun başında durur, ona sakin ve kabullenmiş bakar. 95.86 "öyle hazırlan": yere koyduğu yol çantasını omzuna alır, s21'deki yanan feneri kaldırır ve yola kararlı adımlarla girer; mezarlığın ötesinde şafak aydınlığı belirir (umut).'''),
('s24',97.6,105.6,'İşte hastalık bu nokta-i nazardan hiç aldatmaz bir nâsih ve ikaz edici bir mürşiddir.','''Gece denizi, dalgalar, kayalar; küçük bir kayıkta kürek çeken adam. Yalıyarda bir deniz feneri = hastalık (rehber). 98.68 "İşte hastalık": fener yanar. 99.64 "nokta-i nazardan": fenerin ışık hüzmesi bir bakış gibi süpürür (gerekirse göz biçimli bir çerçeve/iris açılışı). 101.04 "hiç aldatmaz": hüzme sabitlenir ve kayığın önündeki gizli kayaları açığa çıkarır. 102.18 "nâsih": ışık yumuşakça nabız atar. 103.32 "ikaz edici": uyarı çakmaları, kayık kayalardan döner. 104.48 "mürşiddir": hüzme suyun üstüne altın bir yol serer, kayık o yoldan ışıklı, güvenli bir limana süzülür. Alt bantta deniz (sakin doku) — anlamlar orada okunur.'''),
('s25',105.6,110.5,'Ondan şekva değil belki bu cihette ona teşekkür etmek,','''Oda, şafak (scenes/_room.js, mood ≈0.5→0.8: oda ısınır, pencerede şafak). Adam yatakta doğrulmuş. 106.16 "Ondan": başının üstünde karmakarışık, koyu, çizgili bir şikâyet bulutu oluşur. 106.52 "şekva", 106.98 "değil": bulut dağılıp ışık zerrelerine dönüşür. 107.74–108.6 "belki bu cihette": pencereden şafak ışığı yatağa düşer. 109.0–110.04 "ona teşekkür etmek": adam elini kalbine koyar, gözleri kapalı sakin bir gülümsemeyle; pencere önündeki saksıda çiçekler açar.'''),
('s26',110.5,114.7,'eğer fazla ağır gelse sabır istemek gerektir.','''Odada şafak (mood ≈0.8–1). 110.92–112.26 "eğer fazla ağır gelse": adamın omuzlarına ağır, koyu bir taş/yük biner, hafifçe eğilir. 112.62 "sabır istemek": adam (yatakta ya da pencere önünde seccadede diz çökmüş) ellerini avuçları yukarı dua için kaldırır; taş ışığa dönüşüp çözülür; pencere önünde çatlak bir kayadan bir fidan filizlenip sabırla büyür; güneş doğar. 113.88 sonrası: dingin, aydınlık son kare (114.2–114.7 arası çok yavaş, sonra kitaplara geçiş).'''),
('s27',114.7,122.0,'(kaynak)','Gerçekçi Risale-i Nur ve Kur\'an fotoğrafı + kaynak yazısı. (Ayrı yapılıyor; dokunma.)'),
]
out = ['# Senaryo ve zamanlama\n', 'Zamanlar küresel saniyedir (ses kaydındaki kelimenin ilk harfi, ±0.03 sn). Anlam (gloss) satırları motor tarafından çizilir.\n']
for sid, a, b, txt, desc in S:
    words = [w for w in tm['words'] if a - 0.05 <= w['s'] < b]
    g = [x for x in gl if a <= x['t'] < b]
    out.append(f"\n## {sid} — {a:.2f}–{b:.2f} sn\n**Metin:** {txt}\n\n**Kelimeler:** " + ', '.join(f"{w['orig'].strip(',.:!\"')} {w['s']:.2f}" for w in words))
    if g: out.append('\n\n**Ekranda çıkacak anlamlar (motor çizer):** ' + ', '.join(f"\"{x['text']}\" {x['t']:.2f}" for x in g))
    out.append('\n\n**Görsel:** ' + desc + '\n')
open('STORYBOARD.md','w').write('\n'.join(out))
print(open('STORYBOARD.md').read()[:3000])
